 "content": "def transform(grid):
    """Insert 2 into every single-cell gap flanked by equal markers in a row."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c - 1] == row[c + 1] and row[c] != row[c - 1]:
                out[r][c] = 2
